-- Read-only baseline before milestone 6 (SQL Editor). One SELECT; it changes nothing. Every row should say OK. Run it
-- after checks/m3_post_seed.sql and checks/m4_post_seed.sql (both all OK). It confirms milestone 6 is not applied and that
-- the 9 packages the milestone 6 seed will supersede are still milestone 3's published version 1.
with rows_out(ord, check_name, value, ok) as (
  select 10, 'Milestone 6 not applied yet (no screening_summaries table)',
         case when to_regclass('public.screening_summaries') is null then 'not applied' else 'APPLIED' end,
         to_regclass('public.screening_summaries') is null
  union all
  select 11, 'Seed targets: milestone 3 version 1 published for the 9 Harbor candidates with a screening call (expected 9)',
         (select count(*) from public.submission_packages where state = 'published' and id in (md5('portal-m3:package:harbor:tb-isl:1')::uuid, md5('portal-m3:package:harbor:tb-rsm:1')::uuid, md5('portal-m3:package:harbor:je-isl:1')::uuid, md5('portal-m3:package:harbor:pr-isl:1')::uuid, md5('portal-m3:package:harbor:en-pa:1')::uuid, md5('portal-m3:package:harbor:so-pa:1')::uuid, md5('portal-m3:package:harbor:gl-rsm:1')::uuid, md5('portal-m3:package:harbor:ab-fsr:1')::uuid, md5('portal-m3:package:harbor:cm-rsm:1')::uuid))::text,
         (select count(*) from public.submission_packages where state = 'published' and id in (md5('portal-m3:package:harbor:tb-isl:1')::uuid, md5('portal-m3:package:harbor:tb-rsm:1')::uuid, md5('portal-m3:package:harbor:je-isl:1')::uuid, md5('portal-m3:package:harbor:pr-isl:1')::uuid, md5('portal-m3:package:harbor:en-pa:1')::uuid, md5('portal-m3:package:harbor:so-pa:1')::uuid, md5('portal-m3:package:harbor:gl-rsm:1')::uuid, md5('portal-m3:package:harbor:ab-fsr:1')::uuid, md5('portal-m3:package:harbor:cm-rsm:1')::uuid)) = 9
  union all
  select 12, 'No other published package for those 9 submissions, and no milestone 6 package version yet (expected 0 / 0)',
         (select count(*) from public.submission_packages where state = 'published' and submission_id in (select submission_id from public.submission_packages where id in (md5('portal-m3:package:harbor:tb-isl:1')::uuid, md5('portal-m3:package:harbor:tb-rsm:1')::uuid, md5('portal-m3:package:harbor:je-isl:1')::uuid, md5('portal-m3:package:harbor:pr-isl:1')::uuid, md5('portal-m3:package:harbor:en-pa:1')::uuid, md5('portal-m3:package:harbor:so-pa:1')::uuid, md5('portal-m3:package:harbor:gl-rsm:1')::uuid, md5('portal-m3:package:harbor:ab-fsr:1')::uuid, md5('portal-m3:package:harbor:cm-rsm:1')::uuid)) and id not in (md5('portal-m3:package:harbor:tb-isl:1')::uuid, md5('portal-m3:package:harbor:tb-rsm:1')::uuid, md5('portal-m3:package:harbor:je-isl:1')::uuid, md5('portal-m3:package:harbor:pr-isl:1')::uuid, md5('portal-m3:package:harbor:en-pa:1')::uuid, md5('portal-m3:package:harbor:so-pa:1')::uuid, md5('portal-m3:package:harbor:gl-rsm:1')::uuid, md5('portal-m3:package:harbor:ab-fsr:1')::uuid, md5('portal-m3:package:harbor:cm-rsm:1')::uuid))
           || ' / ' || (select count(*) from public.submission_packages where id in (md5('portal-m6:package:harbor:tb-isl')::uuid, md5('portal-m6:package:harbor:tb-rsm')::uuid, md5('portal-m6:package:harbor:je-isl')::uuid, md5('portal-m6:package:harbor:pr-isl')::uuid, md5('portal-m6:package:harbor:en-pa')::uuid, md5('portal-m6:package:harbor:so-pa')::uuid, md5('portal-m6:package:harbor:gl-rsm')::uuid, md5('portal-m6:package:harbor:ab-fsr')::uuid, md5('portal-m6:package:harbor:cm-rsm')::uuid)),
         not exists (select 1 from public.submission_packages where state = 'published' and submission_id in (select submission_id from public.submission_packages where id in (md5('portal-m3:package:harbor:tb-isl:1')::uuid, md5('portal-m3:package:harbor:tb-rsm:1')::uuid, md5('portal-m3:package:harbor:je-isl:1')::uuid, md5('portal-m3:package:harbor:pr-isl:1')::uuid, md5('portal-m3:package:harbor:en-pa:1')::uuid, md5('portal-m3:package:harbor:so-pa:1')::uuid, md5('portal-m3:package:harbor:gl-rsm:1')::uuid, md5('portal-m3:package:harbor:ab-fsr:1')::uuid, md5('portal-m3:package:harbor:cm-rsm:1')::uuid)) and id not in (md5('portal-m3:package:harbor:tb-isl:1')::uuid, md5('portal-m3:package:harbor:tb-rsm:1')::uuid, md5('portal-m3:package:harbor:je-isl:1')::uuid, md5('portal-m3:package:harbor:pr-isl:1')::uuid, md5('portal-m3:package:harbor:en-pa:1')::uuid, md5('portal-m3:package:harbor:so-pa:1')::uuid, md5('portal-m3:package:harbor:gl-rsm:1')::uuid, md5('portal-m3:package:harbor:ab-fsr:1')::uuid, md5('portal-m3:package:harbor:cm-rsm:1')::uuid))
           and not exists (select 1 from public.submission_packages where id in (md5('portal-m6:package:harbor:tb-isl')::uuid, md5('portal-m6:package:harbor:tb-rsm')::uuid, md5('portal-m6:package:harbor:je-isl')::uuid, md5('portal-m6:package:harbor:pr-isl')::uuid, md5('portal-m6:package:harbor:en-pa')::uuid, md5('portal-m6:package:harbor:so-pa')::uuid, md5('portal-m6:package:harbor:gl-rsm')::uuid, md5('portal-m6:package:harbor:ab-fsr')::uuid, md5('portal-m6:package:harbor:cm-rsm')::uuid))
  union all
  select 13, 'Jordan Ellis'' version 2 is still a draft (the seed adds version 3; expected draft)',
         coalesce((select state from public.submission_packages where id = md5('portal-m3:package:harbor:je-isl:2')::uuid), 'MISSING'),
         (select state from public.submission_packages where id = md5('portal-m3:package:harbor:je-isl:2')::uuid) = 'draft'
)
select check_name as "check", value, case when ok then 'OK' else 'STOP' end as result
from rows_out
order by ord;
